import struct, sys
def build(out, bits=64, endian='little', phdrs=None, shdrs=None, extra=b''):
    le = endian=='little'; pre = '<' if le else '>'
    ident = bytearray(16); ident[0:4]=b'\x7fELF'
    ident[4]=2 if bits==64 else 1; ident[5]=1 if le else 2; ident[6]=1
    eh=64 if bits==64 else 52; phes=56 if bits==64 else 32; shes=64 if bits==64 else 40
    phdrs = phdrs or []; shdrs = shdrs or []
    phoff = eh if phdrs else 0
    shoff = eh + len(phdrs)*phes if shdrs else 0
    if bits==64:
        ehdr = struct.pack(pre+"HHIQQQIHHHHHH",2,62,1,0x1000,phoff,shoff,0,eh,phes,len(phdrs),shes,len(shdrs),0)
        def ph(t,fl,off,va,pa,fs,ms,al): return struct.pack(pre+"IIQQQQQQ",t,fl,off,va,pa,fs,ms,al)
        def sh(nm,t,fl,addr,off,sz,lk,inf,al,es): return struct.pack(pre+"IIQQQQIIQQ",nm,t,fl,addr,off,sz,lk,inf,al,es)
    else:
        ehdr = struct.pack(pre+"HHIIIIIHHHHHH",2,62,1,0x1000,phoff,shoff,0,eh,phes,len(phdrs),shes,len(shdrs),0)
        def ph(t,off,va,pa,fs,ms,fl,al): return struct.pack(pre+"IIIIIIII",t,off,va,pa,fs,ms,fl,al)
        def sh(nm,t,fl,addr,off,sz,lk,inf,al,es): return struct.pack(pre+"IIIIIIIIII",nm,t,fl,addr,off,sz,lk,inf,al,es)
    size = eh + len(phdrs)*phes + len(shdrs)*shes
    end = size + len(extra)
    for p in phdrs:
        end = max(end, (p[2] if bits==64 else p[1]) + (p[5] if bits==64 else p[4]))
    for s in shdrs:
        if s[1] != 8:  # not NOBITS
            end = max(end, s[4]+s[5])
    buf = bytearray(end)
    buf[0:16]=ident; buf[16:16+len(ehdr)]=ehdr
    for i,p in enumerate(phdrs): buf[phoff+i*phes:phoff+i*phes+phes]=ph(*p)
    for i,s in enumerate(shdrs): buf[shoff+i*shes:shoff+i*shes+shes]=sh(*s)
    buf[size:size+len(extra)] = extra
    open(out,'wb').write(bytes(buf))

