import struct, sys

ESC = {'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}

def parse(data):
    assert data[:4]==b'\x7fELF'
    is64 = data[4]==2
    le = data[5]==1
    pre = '<' if le else '>'
    if is64:
        f = struct.unpack_from(pre+"HHIQQQIHHHHHH", data, 16)
        keys = ['e_type','e_machine','e_version','e_entry','e_phoff','e_shoff','e_flags',
                'e_ehsize','e_phentsize','e_phnum','e_shentsize','e_shnum','e_shstrndx']
        PHE, SHE = 56, 64
    else:
        f = struct.unpack_from(pre+"HHIIIIIHHHHHH", data, 16)
        keys = ['e_type','e_machine','e_version','e_entry','e_phoff','e_shoff','e_flags',
                'e_ehsize','e_phentsize','e_phnum','e_shentsize','e_shnum','e_shstrndx']
        PHE, SHE = 32, 40
    e = dict(zip(keys,f))
    phdrs=[]; shdrs=[]
    for i in range(e['e_phnum']):
        off = e['e_phoff'] + i*PHE
        if is64:
            v = struct.unpack_from(pre+"IIQQQQQQ", data, off)
            phdrs.append(dict(zip(['p_type','p_flags','p_offset','p_vaddr','p_paddr','p_filesz','p_memsz','p_align'],v)))
        else:
            v = struct.unpack_from(pre+"IIIIIIII", data, off)
            phdrs.append(dict(zip(['p_type','p_offset','p_vaddr','p_paddr','p_filesz','p_memsz','p_flags','p_align'],v)))
    for i in range(e['e_shnum']):
        off = e['e_shoff'] + i*SHE
        if is64:
            v = struct.unpack_from(pre+"IIQQQQIIQQ", data, off)
        else:
            v = struct.unpack_from(pre+"IIIIIIIIII", data, off)
        shdrs.append(dict(zip(['sh_name','sh_type','sh_flags','sh_addr','sh_offset','sh_size','sh_link','sh_info','sh_addralign','sh_entsize'],v)))
    return is64, e, phdrs, shdrs

# priority classes (higher opens first at same start)
SEG, PHDR, PFIELD, SECT, SHDR, SFIELD, EHDR, IDENT, IFIELD, EFIELD = range(10,0,-1)

def ranges(is64, e, phdrs, shdrs):
    R=[]  # (start,end,prio,seq,opentag)
    seq=[0]
    def add(s,t,prio,tag):
        R.append((s,t,prio,seq[0],tag)); seq[0]+=1
    eh = 64 if is64 else 52
    add(0, eh, EHDR, "<span class='ehdr'>")
    add(0,16,IDENT,"<span class='ident'>")
    for nm,s,t in [('magic',0,4),('class',4,5),('data',5,6),('ver',6,7),('abi',7,8),('abi_ver',8,9),('pad',9,16)]:
        add(s,t,IFIELD,"<span class='%s'>"%nm)
    if is64:
        ef=[('e_type',16,18),('e_machine',18,20),('e_version',20,24),('e_entry',24,32),
            ('e_phoff',32,40),('e_shoff',40,48),('e_flags',48,52),('e_ehsize',52,54),
            ('e_phentsize',54,56),('e_phnum',56,58),('e_shentsize',58,60),('e_shnum',60,62),('e_shstrndx',62,64)]
        pf=['p_type','p_flags','p_offset','p_vaddr','p_paddr','p_filesz','p_memsz','p_align']
        ps=[4,4,8,8,8,8,8,8]
        sf=['sh_name','sh_type','sh_flags','sh_addr','sh_offset','sh_size','sh_link','sh_info','sh_addralign','sh_entsize']
        ss=[4,4,8,8,8,8,4,4,8,8]
    else:
        ef=[('e_type',16,18),('e_machine',18,20),('e_version',20,24),('e_entry',24,28),
            ('e_phoff',28,32),('e_shoff',32,36),('e_flags',36,40),('e_ehsize',40,42),
            ('e_phentsize',42,44),('e_phnum',44,46),('e_shentsize',46,48),('e_shnum',48,50),('e_shstrndx',50,52)]
        pf=['p_type','p_offset','p_vaddr','p_paddr','p_filesz','p_memsz','p_flags','p_align']
        ps=[4]*8
        sf=['sh_name','sh_type','sh_flags','sh_addr','sh_offset','sh_size','sh_link','sh_info','sh_addralign','sh_entsize']
        ss=[4]*10
    for nm,s,t in ef:
        add(s,t,EFIELD,"<span class='%s'>"%nm)
    PHE = 56 if is64 else 32
    SHE = 64 if is64 else 40
    for i,p in enumerate(phdrs):
        base = e['e_phoff'] + i*PHE
        add(base, base+PHE, PHDR, "<span class='bin_phdr%d phdr'>"%i)
        o=base
        for nm,sz in zip(pf,ps):
            add(o,o+sz,PFIELD,"<span class='%s'>"%nm); o+=sz
    for i,s in enumerate(shdrs):
        base = e['e_shoff'] + i*SHE
        add(base, base+SHE, SHDR, "<span class='bin_shdr%d shdr'>"%i)
        o=base
        for nm,sz in zip(sf,ss):
            add(o,o+sz,SFIELD,"<span class='%s'>"%nm); o+=sz
    for i,p in enumerate(phdrs):
        if p['p_offset']!=0 and p['p_filesz']!=0:
            add(p['p_offset'], p['p_offset']+p['p_filesz'], SEG, "<span class='bin_segment%d segment'>"%i)
    for i,s in enumerate(shdrs):
        if s['sh_type']!=8 and s['sh_offset']!=0 and s['sh_size']!=0:
            add(s['sh_offset'], s['sh_offset']+s['sh_size'], SECT, "<span class='bin_section%d section hover'>"%i)
    return R

def hexbyte(b):
    return format(b,'02x')

def render(data):
    is64, e, phdrs, shdrs = parse(data)
    R = ranges(is64, e, phdrs, shdrs)
    opens={}; closes={}
    for (s,t,prio,seq,tag) in R:
        opens.setdefault(s,[]).append((prio,seq,tag))
        closes.setdefault(t,[]).append((prio,seq,tag))
    for k in opens: opens[k].sort(key=lambda x:(-x[0],x[1]))
    for k in closes: closes[k].sort(key=lambda x:(x[0],-x[1]))  # LIFO: reverse of open order
    # wait: closes must be reverse of the order they were opened = reverse of opens order
    out=[]
    n=len(data)
    for i in range(n):
        if i in closes:
            for _ in closes[i]: out.append('</span>')
        if i>0:
            out.append('\n' if i%16==0 else ' ')
        if i in opens:
            for (_,_,tag) in opens[i]: out.append(tag)
        b=data[i]
        # magic span char rendering
        if i<4 and 0x21<=b<=0x7e:
            out.append('&nbsp;'+ESC.get(chr(b),chr(b)))
        else:
            out.append(hexbyte(b))
    if n in closes:
        for _ in closes[n]: out.append('</span>')
    bytesdiv=''.join(out)
    # offsets
    off=[]
    i=0
    while i<n:
        off.append(format(i,'x'))
        if i+16<=n: off.append('\n')
        i+=16
    offsetsdiv=''.join(off)
    # ascii
    asc=[]
    for i,b in enumerate(data):
        if i>0 and i%16==0: asc.append('\n')
        if 0x21<=b<=0x7e: asc.append(ESC.get(chr(b),chr(b)))
        else: asc.append('.')
    if n%16==0: asc.append('\n')
    asciidiv=''.join(asc)
    return offsetsdiv, bytesdiv, asciidiv

if __name__=='__main__':
    fn=sys.argv[1]
    data=open(fn,'rb').read()
    o,b,a=render(data)
    h=open(fn+'.html').read()
    ro=h.split("<div id='offsets'>")[1].split('</div>')[0]
    rb=h.split("<div id='bytes'>")[1].split('</div>')[0]
    ra=h.split("<div id='ascii'>")[1].split('</div>')[0]
    ok=True
    for name,got,exp in [('offsets',o,ro),('bytes',b,rb),('ascii',a,ra)]:
        if got!=exp:
            ok=False
            print(fn, name, 'MISMATCH')
            for j,(x,y) in enumerate(zip(got,exp)):
                if x!=y:
                    print(' first diff at',j,repr(got[max(0,j-40):j+40]),'VS',repr(exp[max(0,j-40):j+40])); break
            else:
                print(' length diff', len(got), len(exp))
    if ok: print(fn,'OK')
